index 0000000..d1499d7
--- /dev/null
+++ b/internal/hosted/llm/gateway.go
@@ -0,0 +1,230 @@
+// Package llm provides the bounded, observable model interface used by hosted
+// review workers. Provider credentials stay inside provider adapters and are
+// never included in requests, cache keys, or call records.
+package llm
+
+import (
+	"context"
+	"crypto/sha256"
+	"encoding/hex"
+	"errors"
+	"fmt"
+	"sync"
+	"time"
+)
+
+type Request struct {
+	Provider        string
+	Model           string
+	System          string
+	Prompt          string
+	MaxOutputTokens int
+	Temperature     float64
+}
+
+type Usage struct {
+	InputTokens     int64
+	OutputTokens    int64
+	CacheReadTokens int64
+}
+
+type Response struct {
+	Text      string
+	Usage     Usage
+	RequestID string
+	Cached    bool
+}
+
+type Provider interface {
+	Name() string
+	Complete(context.Context, Request) (Response, error)
+}
+
+type Cache interface {
+	Get(context.Context, string) (Response, bool, error)
+	Put(context.Context, string, Response, time.Duration) error
+}
+
+type Recorder interface {
+	Record(context.Context, CallRecord)
+}
+
+type CallRecord struct {
+	Provider     string
+	Model        string
+	Duration     time.Duration
+	Attempts     int
+	Usage        Usage
+	CostMicrousd int64
+	Cached       bool
+	CacheErr     string
+	Err          string
+}
+
+type Price struct {
+	InputMicrousdPerMillion     int64
+	OutputMicrousdPerMillion    int64
+	CacheReadMicrousdPerMillion int64
+}
+
+type Gateway struct {
+	Providers  map[string]Provider
+	Cache      Cache
+	Recorder   Recorder
+	Prices     map[string]Price
+	Timeout    time.Duration
+	CacheTTL   time.Duration
+	MaxRetries int
+	Sleep      func(context.Context, time.Duration) error
+}
+
+func (g Gateway) Complete(ctx context.Context, request Request) (response Response, err error) {
+	provider := g.Providers[request.Provider]
+	if provider == nil {
+		return Response{}, fmt.Errorf("unknown LLM provider %q", request.Provider)
+	}
+	if request.Model == "" || request.Prompt == "" || request.MaxOutputTokens <= 0 {
+		return Response{}, errors.New("LLM model, prompt, and positive output-token limit are required")
+	}
+	if request.Temperature < 0 || request.Temperature > 2 {
+		return Response{}, errors.New("LLM temperature must be between 0 and 2")
+	}
+
+	started := time.Now()
+	record := CallRecord{Provider: request.Provider, Model: request.Model}
+	defer func() {
+		record.Duration = time.Since(started)
+		record.Usage = response.Usage
+		record.Cached = response.Cached
+		if !response.Cached {
+			record.CostMicrousd = cost(g.Prices[request.Provider+"/"+request.Model], response.Usage)
+		}
+		if err != nil {
+			record.Err = err.Error()
+		}
+		if g.Recorder != nil {
+			g.Recorder.Record(context.WithoutCancel(ctx), record)
+		}
+	}()
+
+	cacheKey := promptKey(request)
+	if g.Cache != nil {
+		cached, ok, cacheErr := g.Cache.Get(ctx, cacheKey)
+		if cacheErr != nil {
+			record.CacheErr = fmt.Sprintf("read LLM prompt cache: %v", cacheErr)
+		}
+		if cacheErr == nil && ok {
+			cached.Cached = true
+			return cached, nil
+		}
+	}
+
+	timeout := g.Timeout
+	if timeout <= 0 {
+		timeout = 90 * time.Second
+	}
+	maxRetries := g.MaxRetries
+	if maxRetries < 0 {
+		maxRetries = 0
+	}
+	if maxRetries == 0 {
+		maxRetries = 2
+	}
+
+	for attempt := 0; ; attempt++ {
+		record.Attempts = attempt + 1
+		callCtx, cancel := context.WithTimeout(ctx, timeout)
+		response, err = provider.Complete(callCtx, request)
+		cancel()
+		if err == nil {
+			break
+		}
+		var temporary interface{ Temporary() bool }
+		if attempt >= maxRetries || !errors.As(err, &temporary) || !temporary.Temporary() {
+			return Response{}, err
+		}
+		if sleepErr := g.sleep(ctx, time.Duration(1<<attempt)*time.Second); sleepErr != nil {
+			return Response{}, sleepErr
+		}
+	}
+
+	if response.Text == "" {
+		return Response{}, errors.New("LLM provider returned an empty response")
+	}
+	if response.Usage.InputTokens < 0 || response.Usage.OutputTokens < 0 || response.Usage.CacheReadTokens < 0 {
+		return Response{}, errors.New("LLM provider returned invalid token usage")
+	}
+	if g.Cache != nil {
+		ttl := g.CacheTTL
+		if ttl <= 0 {
+			ttl = 15 * time.Minute
+		}
+		if cacheErr := g.Cache.Put(ctx, cacheKey, response, ttl); cacheErr != nil {
+			record.CacheErr = fmt.Sprintf("write LLM prompt cache: %v", cacheErr)
+		}
+	}
+	return response, nil
+}
+
+func (g Gateway) sleep(ctx context.Context, duration time.Duration) error {
+	if g.Sleep != nil {
+		return g.Sleep(ctx, duration)
+	}
+	timer := time.NewTimer(duration)
+	defer timer.Stop()
+	select {
+	case <-ctx.Done():
+		return ctx.Err()
+	case <-timer.C:
+		return nil
+	}
+}
+
+func promptKey(request Request) string {
+	digest := sha256.Sum256([]byte(fmt.Sprintf("%s\x00%s\x00%s\x00%s\x00%d\x00%g", request.Provider, request.Model, request.System, request.Prompt, request.MaxOutputTokens, request.Temperature)))
+	return hex.EncodeToString(digest[:])
+}
+
+func cost(price Price, usage Usage) int64 {
+	return (usage.InputTokens*price.InputMicrousdPerMillion + usage.OutputTokens*price.OutputMicrousdPerMillion + usage.CacheReadTokens*price.CacheReadMicrousdPerMillion) / 1_000_000
+}
+
+type memoryEntry struct {
+	response  Response
+	expiresAt time.Time
+}
+
+type MemoryCache struct {
+	Now func() time.Time
+	mu  sync.Mutex
+	set map[string]memoryEntry
+}
+
+func (c *MemoryCache) Get(_ context.Context, key string) (Response, bool, error) {
+	c.mu.Lock()
+	defer c.mu.Unlock()
+	entry, ok := c.set[key]
+	if !ok || !entry.expiresAt.After(c.now()) {
+		delete(c.set, key)
+		return Response{}, false, nil
+	}
+	return entry.response, true, nil
+}
+
+func (c *MemoryCache) Put(_ context.Context, key string, response Response, ttl time.Duration) error {
+	c.mu.Lock()
+	defer c.mu.Unlock()
+	if c.set == nil {
+		c.set = map[string]memoryEntry{}
+	}
+	response.Cached = false
+	c.set[key] = memoryEntry{response: response, expiresAt: c.now().Add(ttl)}
+	return nil
+}
+
+func (c *MemoryCache) now() time.Time {
+	if c.Now != nil {
+		return c.Now()
+	}
+	return time.Now()
+}

diff --git a/internal/hosted/llm/gateway_test.go b/internal/hosted/llm/gateway_test.go
new file mode 100644
index 0000000..493eab7
--- /dev/null
+++ b/internal/hosted/llm/gateway_test.go
@@ -0,0 +1,125 @@
+package llm
+
+import (
+	"context"
+	"errors"
+	"sync"
+	"testing"
+	"time"
+)
+
+type temporaryError struct{}
+
+func (temporaryError) Error() string   { return "try again" }
+func (temporaryError) Temporary() bool { return true }
+
+type fakeProvider struct {
+	mu       sync.Mutex
+	calls    int
+	failures int
+}
+
+func (*fakeProvider) Name() string { return "fake" }
+
+func (p *fakeProvider) Complete(_ context.Context, _ Request) (Response, error) {
+	p.mu.Lock()
+	defer p.mu.Unlock()
+	p.calls++
+	if p.calls <= p.failures {
+		return Response{}, temporaryError{}
+	}
+	return Response{Text: "review result", Usage: Usage{InputTokens: 1000, OutputTokens: 200, CacheReadTokens: 500}}, nil
+}
+
+type recordingSink struct {
+	records []CallRecord
+}
+
+type brokenCache struct {
+	getErr error
+	putErr error
+}
+
+func (c brokenCache) Get(context.Context, string) (Response, bool, error) {
+	return Response{}, false, c.getErr
+}
+
+func (c brokenCache) Put(context.Context, string, Response, time.Duration) error {
+	return c.putErr
+}
+
+func (r *recordingSink) Record(_ context.Context, record CallRecord) {
+	r.records = append(r.records, record)
+}
+
+func TestGatewayRetriesRecordsCostAndCaches(t *testing.T) {
+	provider := &fakeProvider{failures: 1}
+	recorder := &recordingSink{}
+	cache := &MemoryCache{}
+	gateway := Gateway{
+		Providers: map[string]Provider{"fake": provider}, Cache: cache, Recorder: recorder,
+		Prices: map[string]Price{"fake/model": {InputMicrousdPerMillion: 1_000_000, OutputMicrousdPerMillion: 2_000_000, CacheReadMicrousdPerMillion: 500_000}},
+		Sleep:  func(context.Context, time.Duration) error { return nil },
+	}
+	request := Request{Provider: "fake", Model: "model", Prompt: "review this diff", MaxOutputTokens: 500}
+	first, err := gateway.Complete(context.Background(), request)
+	if err != nil {
+		t.Fatal(err)
+	}
+	if first.Cached || provider.calls != 2 {
+		t.Fatalf("first response cached=%v calls=%d", first.Cached, provider.calls)
+	}
+	second, err := gateway.Complete(context.Background(), request)
+	if err != nil {
+		t.Fatal(err)
+	}
+	if !second.Cached || provider.calls != 2 {
+		t.Fatalf("second response cached=%v calls=%d", second.Cached, provider.calls)
+	}
+	if len(recorder.records) != 2 || recorder.records[0].Attempts != 2 || recorder.records[1].Attempts != 0 {
+		t.Fatalf("records = %+v", recorder.records)
+	}
+	if recorder.records[0].CostMicrousd != 1650 {
+		t.Fatalf("cost = %d microusd, want 1650", recorder.records[0].CostMicrousd)
+	}
+	if recorder.records[1].CostMicrousd != 0 {
+		t.Fatalf("cached call cost = %d microusd, want 0", recorder.records[1].CostMicrousd)
+	}
+}
+
+func TestGatewayDoesNotRetryPermanentErrors(t *testing.T) {
+	provider := permanentProvider{}
+	gateway := Gateway{Providers: map[string]Provider{"permanent": provider}, Sleep: func(context.Context, time.Duration) error { return errors.New("must not sleep") }}
+	_, err := gateway.Complete(context.Background(), Request{Provider: "permanent", Model: "model", Prompt: "prompt", MaxOutputTokens: 1})
+	if err == nil || err.Error() != "invalid request" {
+		t.Fatalf("error = %v", err)
+	}
+}
+
+func TestGatewayFailsOpenWhenOptionalCacheIsUnavailable(t *testing.T) {
+	provider := &fakeProvider{}
+	recorder := &recordingSink{}
+	gateway := Gateway{
+		Providers: map[string]Provider{"fake": provider},
+		Cache:     brokenCache{getErr: errors.New("redis unavailable"), putErr: errors.New("redis unavailable")},
+		Recorder:  recorder,
+	}
+
+	response, err := gateway.Complete(context.Background(), Request{Provider: "fake", Model: "model", Prompt: "prompt", MaxOutputTokens: 1})
+	if err != nil {
+		t.Fatal(err)
+	}
+	if response.Text != "review result" || provider.calls != 1 {
+		t.Fatalf("response = %+v, provider calls = %d", response, provider.calls)
+	}
+	if len(recorder.records) != 1 || recorder.records[0].CacheErr == "" {
+		t.Fatalf("records = %+v", recorder.records)
+	}
+}
+
+type permanentProvider struct{}
+
+func (permanentProvider) Name() string { return "permanent" }
+func (permanentProvider) Complete(context.Context, Request) (Response, error) {
+	return Response{}, errors.New("invalid request")
+}

diff --git a/internal/hosted/llm/providers.go b/internal/hosted/llm/providers.go
new file mode 100644
index 0000000..8d205e5
--- /dev/null
+++ b/internal/hosted/llm/providers.go
@@ -0,0 +1,161 @@
+package llm
+
+import (
+	"bytes"
+	"context"
+	"encoding/json"
+	"fmt"
+	"io"
+	"net/http"
+	"strings"
+)
+
+type ProviderError struct {
+	ProviderName string
+	StatusCode   int
+	Retry        bool
+}
+
+func (e ProviderError) Error() string {
+	return fmt.Sprintf("%s LLM request failed with status %d", e.ProviderName, e.StatusCode)
+}
+
+func (e ProviderError) Temporary() bool { return e.Retry }
+
+type OpenAIProvider struct {
+	APIKey   string
+	Endpoint string
+	HTTP     *http.Client
+}
+
+func (OpenAIProvider) Name() string { return "openai" }
+
+func (p OpenAIProvider) Complete(ctx context.Context, request Request) (Response, error) {
+	payload := map[string]any{
+		"model":             request.Model,
+		"input":             []map[string]string{{"role": "system", "content": request.System}, {"role": "user", "content": request.Prompt}},
+		"max_output_tokens": request.MaxOutputTokens,
+	}
+	endpoint := p.Endpoint
+	if endpoint == "" {
+		endpoint = "https://api.openai.com/v1/responses"
+	}
+	var decoded struct {
+		ID     string `json:"id"`
+		Output []struct {
+			Content []struct {
+				Text string `json:"text"`
+			} `json:"content"`
+		} `json:"output"`
+		Usage struct {
+			InputTokens  int64 `json:"input_tokens"`
+			OutputTokens int64 `json:"output_tokens"`
+			InputDetails struct {
+				CachedTokens int64 `json:"cached_tokens"`
+			} `json:"input_tokens_details"`
+		} `json:"usage"`
+	}
+	if err := postJSON(ctx, p.HTTP, endpoint, map[string]string{"Authorization": "Bearer " + p.APIKey}, payload, &decoded, "openai"); err != nil {
+		return Response{}, err
+	}
+	var text strings.Builder
+	for _, output := range decoded.Output {
+		for _, content := range output.Content {
+			text.WriteString(content.Text)
+		}
+	}
+	return Response{Text: text.String(), RequestID: decoded.ID, Usage: Usage{InputTokens: decoded.Usage.InputTokens, OutputTokens: decoded.Usage.OutputTokens, CacheReadTokens: decoded.Usage.InputDetails.CachedTokens}}, nil
+}
+
+type AnthropicProvider struct {
+	APIKey   string
+	Endpoint string
+	Version  string
+	HTTP     *http.Client
+}
+
+func (AnthropicProvider) Name() string { return "anthropic" }
+
+func (p AnthropicProvider) Complete(ctx context.Context, request Request) (Response, error) {
+	payload := map[string]any{
+		"model": request.Model, "system": request.System,
+		"messages":   []map[string]string{{"role": "user", "content": request.Prompt}},
+		"max_tokens": request.MaxOutputTokens, "temperature": request.Temperature,
+	}
+	endpoint := p.Endpoint
+	if endpoint == "" {
+		endpoint = "https://api.anthropic.com/v1/messages"
+	}
+	version := p.Version
+	if version == "" {
+		version = "2023-06-01"
+	}
+	var decoded struct {
+		ID      string `json:"id"`
+		Content []struct {
+			Text string `json:"text"`
+		} `json:"content"`
+		Usage struct {
+			InputTokens          int64 `json:"input_tokens"`
+			OutputTokens         int64 `json:"output_tokens"`
+			CacheReadInputTokens int64 `json:"cache_read_input_tokens"`
+		} `json:"usage"`
+	}
+	if err := postJSON(ctx, p.HTTP, endpoint, map[string]string{"x-api-key": p.APIKey, "anthropic-version": version}, payload, &decoded, "anthropic"); err != nil {
+		return Response{}, err
+	}
+	var text strings.Builder
+	for _, content := range decoded.Content {
+		text.WriteString(content.Text)
+	}
+	return Response{Text: text.String(), RequestID: decoded.ID, Usage: Usage{InputTokens: decoded.Usage.InputTokens, OutputTokens: decoded.Usage.OutputTokens, CacheReadTokens: decoded.Usage.CacheReadInputTokens}}, nil
+}
+
+// BedrockInvoker is implemented by the deployment's AWS SDK adapter. Keeping
+// signing outside this package makes the gateway testable and avoids handling
+// long-lived AWS credentials.
+type BedrockInvoker interface {
+	InvokeModel(context.Context, string, Request) (Response, error)
+}
+
+type BedrockProvider struct{ Invoker BedrockInvoker }
+
+func (BedrockProvider) Name() string { return "bedrock" }
+
+func (p BedrockProvider) Complete(ctx context.Context, request Request) (Response, error) {
+	if p.Invoker == nil {
+		return Response{}, fmt.Errorf("bedrock invoker is required")
+	}
+	return p.Invoker.InvokeModel(ctx, request.Model, request)
+}
+
+func postJSON(ctx context.Context, client *http.Client, endpoint string, headers map[string]string, payload any, output any, provider string) error {
+	body, err := json.Marshal(payload)
+	if err != nil {
+		return err
+	}
+	request, err := http.NewRequestWithContext(ctx, http.MethodPost, endpoint, bytes.NewReader(body))
+	if err != nil {
+		return err
+	}
+	request.Header.Set("Content-Type", "application/json")
+	for name, value := range headers {
+		request.Header.Set(name, value)
+	}
+	if client == nil {
+		client = http.DefaultClient
+	}
+	response, err := client.Do(request)
+	if err != nil {
+		return err
+	}
+	defer response.Body.Close()
+	if response.StatusCode < 200 || response.StatusCode >= 300 {
+		_, _ = io.Copy(io.Discard, response.Body)
+		return ProviderError{ProviderName: provider, StatusCode: response.StatusCode, Retry: response.StatusCode == http.StatusTooManyRequests || response.StatusCode >= 500}
+	}
+	if err := json.NewDecoder(io.LimitReader(response.Body, 8<<20)).Decode(output); err != nil {
+		return fmt.Errorf("decode %s LLM response: %w", provider, err)
+	}
+	return nil
+}
